import React, {useEffect, useMemo, useRef, useState} from 'react';
import {createRoot} from 'react-dom/client';
import {onAuthStateChanged, createUserWithEmailAndPassword, signInWithEmailAndPassword, sendPasswordResetEmail, signOut} from 'firebase/auth';
import {ref, onValue, runTransaction} from 'firebase/database';
import {httpsCallable} from 'firebase/functions';
import {Home, Users, Plus, CalendarCheck, MoreHorizontal, Bell, ChevronDown, ChevronRight, ArrowLeft, Landmark, Pencil, Trash2, Wallet, HandCoins, CreditCard, ChartColumnIncreasing, FileDown, ShieldCheck, Cloud, CloudOff, CircleCheck, Search, CircleAlert, Check, History, Settings, LogOut, Download, Upload, LockKeyhole, Eye, EyeOff, RefreshCw, CalendarDays, UserRound, CircleHelp, BriefcaseBusiness, Ellipsis, X, ArrowUpRight, ArrowDownRight, FileSpreadsheet, Receipt, PiggyBank, HousePlus, Undo2, Building2, Menu} from 'lucide-react';
import {auth,database,functions,enabled} from './firebase.mjs';
import {emptyState,demoState,reduceState,applyDueInterest,rows,businessBalance,loanBalance,monthlySummary,asMoney,money,id,today,addMonths,validateBackup,PAYMENT_METHODS} from './domain.mjs';
import './style.css';
const COLORS=['#155cfb','#8b63ee','#0aaf88','#ef9a28','#f05b78','#314e8a'];
const isoNow=()=>new Date().toISOString();
const shortDate=x=>{try{return new Intl.DateTimeFormat('es-CO',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(x+'T12:00:00Z'))}catch{return x}};
const pickName=s=>s?.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase() || 'CL';
function Brand({large=false}){return <div className={`brand ${large?'brand-large':''}`}><span className="brand-logo"><svg viewBox="0 0 96 96" aria-hidden="true"><defs><linearGradient id="gradientLogo" x1="0" y1="0" x2="1" y2="1"><stop stopColor="#69c5ff"/><stop offset="1" stopColor="#0750ef"/></linearGradient></defs><path fill="url(#gradientLogo)" d="M25 77 43 19h25c25 0 27 35 4 42H46l9-15h11c9 0 9-12 0-12H53L40 77z"/><path d="M21 68 54 29" fill="none" stroke="#176bff" strokeWidth="12" strokeLinecap="round"/></svg></span><span>Prestamo<span className="brand-blue">App</span></span></div>}
function Btn({children,onClick,variant='primary',icon:Icon,disabled=false,style={},type='button'}){return <button type={type} className={`btn btn-${variant}`} onClick={onClick} disabled={disabled} style={style}>{Icon&&<Icon size={17}/>} {children}</button>}
function IconButton({icon:Icon,onClick,title,variant=''}){return <button className={`icon-btn ${variant}`} title={title} aria-label={title} onClick={onClick}><Icon size={19}/></button>}
function Card({children,className=''}){return <div className={`card ${className}`}>{children}</div>}
function Mini({icon:Icon,label,value,tone='blue',onClick}){return <button className="metric" onClick={onClick} disabled={!onClick}><div className={`tile-icon ${tone}`}><Icon size={19}/></div><span className="metric-label">{label}</span><strong>{value}</strong></button>}
function Header({title,onBack,right}){return <div className="view-header"><div className="flex align-center gap10">{onBack&&<IconButton icon={ArrowLeft} onClick={onBack} title="Regresar"/>}<h2>{title}</h2></div>{right}</div>}
function Segmented({options,value,onChange}){return <div className="segmented">{options.map(o=><button key={o.value} className={value===o.value?'active':''} onClick={()=>onChange(o.value)}>{o.label}</button>)}</div>}
function Labeled({label,children,hint}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
const txt=(setter,key)=>(e)=>setter(v=>({...v,[key]:e.target.value}));
const int=n=>Number(n||0);
const METHODS=Object.entries(PAYMENT_METHODS).map(([value,label])=>({value,label}));
const paidBackupEnabled=import.meta.env.VITE_ENABLE_PAID_BACKUPS==='true';
const getError=e=>{
  const code=String(e?.code||'');
  if(code.includes('auth/invalid-credential')||code.includes('auth/wrong-password'))return 'Correo o contraseña incorrectos.';
  if(code.includes('auth/email-already-in-use'))return 'Este correo ya tiene una cuenta.';
  if(code.includes('auth/weak-password'))return 'La contraseña debe tener al menos 6 caracteres.';
  if(code.includes('permission-denied'))return 'No hay permiso para guardar. Revisa las reglas de Firebase.';
  return e?.message||'No se pudo completar la operación.';
};
function App(){
  const [ready,setReady]=useState(!enabled), [user,setUser]=useState(null),[showWelcome,setShowWelcome]=useState(true);
  const [dbState,setDbState]=useState(()=>{if(enabled)return emptyState();try{const data=localStorage.getItem('prestamoapp_demo_v1');return data?JSON.parse(data):demoState()}catch{return demoState()}});
  const [businessId,setBusinessId]=useState(()=>localStorage.getItem('prestamoapp_business')||'');
  const [page,setPage]=useState('inicio'),[clientId,setClientId]=useState(null),[loanId,setLoanId]=useState(null);
  const [modal,setModal]=useState(null),[busy,setBusy]=useState(false),[toast,setToast]=useState('');
  const [search,setSearch]=useState(''),[filter,setFilter]=useState('todos'),[paymentFilter,setPaymentFilter]=useState('todos');
  const [loginMode,setLoginMode]=useState('login'),[loginForm,setLoginForm]=useState({email:'',password:''}),[showPassword,setShowPassword]=useState(false);
  const [backupStatus,setBackupStatus]=useState(null),[backupBusy,setBackupBusy]=useState(false);
  const [freeBackup,setFreeBackup]=useState(null);
  const [month,setMonth]=useState(today().slice(0,7));
  const [noticeFilter,setNoticeFilter]=useState('todos');
  const [showBell,setShowBell]=useState(false);
  const [notificationsEnabled,setNotificationsEnabled]=useState(()=>localStorage.getItem('prestamoapp_notifications')!=='off');
  useEffect(()=>{localStorage.setItem('prestamoapp_notifications',notificationsEnabled?'on':'off')},[notificationsEnabled]);
  const [readNotices,setReadNotices]=useState(()=>{try{return JSON.parse(localStorage.getItem('prestamoapp_read_notices')||'{}')}catch{return {}}});
  useEffect(()=>{localStorage.setItem('prestamoapp_read_notices',JSON.stringify(readNotices))},[readNotices]);
  const fileInput=useRef(null),billingRef=useRef(false);
  const inform=(s)=>{setToast(s);window.setTimeout(()=>setToast(''),4500)};
  useEffect(()=>{const t=setTimeout(()=>setShowWelcome(false),950);return()=>clearTimeout(t)},[]);
  useEffect(()=>{if(!enabled)return;return onAuthStateChanged(auth,u=>{setUser(u);setReady(true);if(!u){setDbState(emptyState());setPage('inicio')}})},[]);
  useEffect(()=>{if(!enabled||!user)return;const dataRef=ref(database,`accounts/${user.uid}/data`);return onValue(dataRef,snap=>{setDbState(snap.val()||emptyState())},err=>inform(`Error de lectura: ${getError(err)}`))},[user]);
  useEffect(()=>{if(!enabled){localStorage.setItem('prestamoapp_demo_v1',JSON.stringify(dbState))}},[dbState]);
  useEffect(()=>{if(!enabled||!user){setFreeBackup(null);return;}return onValue(ref(database,`accounts/${user.uid}/backupMeta`),snap=>setFreeBackup(snap.val()||null),()=>setFreeBackup(null))},[user?.uid]);
  const businesses=rows(dbState.businesses).sort((a,b)=>a.createdAt.localeCompare(b.createdAt));
  const currentId=businesses.some(b=>b.id===businessId)?businessId:businesses[0]?.id;
  const current=businesses.find(b=>b.id===currentId);
  useEffect(()=>{if(currentId){localStorage.setItem('prestamoapp_business',currentId)}},[currentId]);
  const clients=rows(dbState.clients).filter(c=>c.businessId===currentId).sort((a,b)=>a.name.localeCompare(b.name));
  const loans=rows(dbState.loans).filter(l=>l.businessId===currentId&&!l.voidedAt).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  const payments=rows(dbState.payments).filter(p=>p.businessId===currentId&&!p.voidedAt).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));
  const totals=currentId?businessBalance(dbState,currentId):{capitalTotal:0,available:0,principalDue:0,interestDue:0,interestEarned:0,loanCount:0,clientCount:0};
  const person=dbState.clients[clientId], loan=dbState.loans[loanId];
  const dateDue=loans.some(l=>l.interestPlan!=='manual'&&l.nextInterestDate&&l.nextInterestDate<=today());
  const noticeItems=useMemo(()=>{
    const output=[];
    const currentDay=today();
    const near=new Date(currentDay+'T12:00:00Z');near.setUTCDate(near.getUTCDate()+3);const nearDay=near.toISOString().slice(0,10);
    for(const l of loans){
      const bal=loanBalance(dbState,l);
      if(bal.principalDue<=0&&bal.interestDue<=0)continue;
      const due=l.nextInterestDate?addMonths(l.nextInterestDate,-1):l.firstDueDate;
      if(due<=nearDay)output.push({id:`due_${l.id}_${due}`,type:'vencimientos',title:due<currentDay?'Préstamo vencido':due===currentDay?'Vence hoy':'Próximo vencimiento',detail:`${dbState.clients[l.clientId]?.name||'Cliente'} · Interés por cobrar ${money(bal.interestDue)}`,date:due,loanId:l.id});
    }
    for(const pay of payments.slice(0,12))output.push({id:`paid_${pay.id}`,type:'pagos',title:'Pago registrado',detail:`${dbState.clients[pay.clientId]?.name||'Cliente'} · ${money(pay.capital+pay.interest)} · ${PAYMENT_METHODS[pay.method||'cash']}`,date:pay.date,loanId:pay.loanId});
    if(freeBackup?.status==='error')output.unshift({id:'backup_error_'+freeBackup.at,type:'sistema',title:'Error de respaldo',detail:freeBackup.message||'Revisa el respaldo en Apps Script',date:(freeBackup.at||'').slice(0,10)});
    return output.sort((a,b)=>b.date.localeCompare(a.date)).slice(0,35);
  },[dbState,currentId,freeBackup,loans.length,payments.length]);
  const unseenCount=notificationsEnabled?noticeItems.filter(n=>!readNotices[n.id]).length:0;
  useEffect(()=>{if(!ready||(enabled&&!user)||!dateDue||billingRef.current)return;billingRef.current=true;doAction('BILL_INTEREST',{date:today()},false).finally(()=>{billingRef.current=false})},[ready,user?.uid,dateDue]);
  async function doAction(kind,payload,success=true){
    const action={kind,payload,opId:id(),at:isoNow()};setBusy(true);
    try{
      if(enabled){if(!user)throw Error('Inicia sesión para guardar.');
        let issue;
        const result=await runTransaction(ref(database,`accounts/${user.uid}/data`),curr=>{try{issue=null;return reduceState(curr||emptyState(),action)}catch(e){issue=e;return}}, {applyLocally:false});
        if(!result.committed) throw issue||Error('No se pudo guardar el cambio.');
      }else setDbState(s=>reduceState(s,action));
      if(success)inform('Guardado correctamente.');return true;
    }catch(e){inform(getError(e));return false}finally{setBusy(false)}
  }
  const go=(where)=>{setPage(where);setSearch('');setFilter('todos');window.scrollTo(0,0)};
  const detailClient=(c)=>{setClientId(c.id);go('cliente')};
  const detailLoan=(l)=>{setLoanId(l.id);setClientId(l.clientId);go('prestamo')};
  async function login(e){e.preventDefault();setBusy(true);try{
    if(loginMode==='register')await createUserWithEmailAndPassword(auth,loginForm.email,loginForm.password);
    else if(loginMode==='reset'){await sendPasswordResetEmail(auth,loginForm.email);inform('Enviamos el enlace para recuperar tu contraseña.');setLoginMode('login')}
    else await signInWithEmailAndPassword(auth,loginForm.email,loginForm.password);
  }catch(e){inform(getError(e))}finally{setBusy(false)}}
  function saveFile(){
    const doc={format:'PrestamoAppBackup',version:1,exportedAt:isoNow(),uid:user?.uid||null,email:user?.email||null,data:dbState};
    const blob=new Blob([JSON.stringify(doc,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
    a.href=url;a.download=`PrestamoApp_respaldo_${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);inform('Se descargó el respaldo JSON. Consérvalo en un lugar seguro.');
  }
  async function restoreFile(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;try{
    const raw=JSON.parse(await file.text()),data=validateBackup(raw);
    if(enabled&&raw.uid&&raw.uid!==user?.uid)throw Error('Este respaldo pertenece a otra cuenta.');
    const summary=`${rows(data.businesses).length} negocios, ${rows(data.clients).length} clientes, ${rows(data.loans).length} préstamos y ${rows(data.payments).length} pagos`;
    if(prompt(`RESTAURAR RESPALDO (${summary}). Reemplazará TODOS los datos de esta cuenta. Para confirmar escribe REEMPLAZAR:`)!=='REEMPLAZAR')return;
    if(!window.confirm('Última confirmación: ¿reemplazar por completo los datos actuales?'))return;
    setBusy(true);
    // Antes de sustituir cualquier dato financiero, descarga una copia preventiva.
    const pre={format:'PrestamoAppBackup',version:1,exportedAt:isoNow(),uid:user?.uid||null,data:dbState};
    const blob=new Blob([JSON.stringify(pre,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');
    anchor.href=url;anchor.download=`PrestamoApp_ANTES_RESTAURACION_${today()}.json`;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);
    if(enabled){if(!user)throw Error('Inicia sesión para restaurar.');await runTransaction(ref(database,`accounts/${user.uid}/data`),curr=>({...data,revision:(curr?.revision||0)+1}),{applyLocally:false})}
    else setDbState({...data,revision:(dbState.revision||0)+1});
    setPage('inicio');setBusinessId('');inform('Respaldo restaurado. Revisa los saldos antes de operar.');
  }catch(err){inform(getError(err))}finally{setBusy(false)}}
  async function cloudCall(name,payload={}){if(!enabled||!user)throw Error('Conecta Firebase para usar las copias automáticas.');return (await httpsCallable(functions,name)(payload)).data}
  async function loadBackup(){if(!enabled||!paidBackupEnabled)return;setBackupBusy(true);try{setBackupStatus(await cloudCall('backupStatus'))}catch(e){inform(`No se pudo consultar el respaldo: ${getError(e)}`)}finally{setBackupBusy(false)}}
  useEffect(()=>{if(page==='respaldo'&&enabled&&user&&paidBackupEnabled)loadBackup()},[page,user?.uid]);
  async function manualCloudBackup(){setBackupBusy(true);try{const x=await cloudCall('backupManual');inform(`Copia en la nube creada${x.sheetsSynced?' y sincronizada con Google Sheets':''}.`);await loadBackup()}catch(e){inform(getError(e))}finally{setBackupBusy(false)}}
  async function restoreRemote(provider){
    const from=provider==='cloud'?'Cloud Storage':'Google Sheets';
    const confirmation=window.prompt(`Restaurar desde ${from} REEMPLAZARÁ toda la información actual. Escribe RESTAURAR para continuar:`);
    if(confirmation!=='RESTAURAR'||!window.confirm(`¿Confirmas que deseas recuperar la última copia guardada en ${from}?`))return;
    setBackupBusy(true);
    try{const result=await cloudCall(provider==='cloud'?'restoreCloudBackup':'restoreGoogleSheets',{confirmation:'RESTAURAR'});inform(`Se restauraron ${result.clients} clientes y ${result.loans} préstamos. Verifica tus saldos.`);go('inicio')}
    catch(e){inform(getError(e))}finally{setBackupBusy(false)}
  }
  async function connectSheets(){setBackupBusy(true);try{const result=await cloudCall('connectGoogleSheets');window.location.assign(result.url)}catch(e){inform(getError(e));setBackupBusy(false)}}
  async function disconnectSheets(){if(!window.confirm('¿Desconectar Google Sheets? El archivo existente no se eliminará.'))return;setBackupBusy(true);try{await cloudCall('disconnectGoogleSheets');await loadBackup();inform('Google Sheets desconectado.')}catch(e){inform(getError(e))}finally{setBackupBusy(false)}}
  const nav = (active)=> <nav className="tabbar" aria-label="Navegación"><button className={active==='inicio'?'selected':''} onClick={()=>go('inicio')}><Home size={21}/><span>Inicio</span></button><button className={active==='clientes'?'selected':''} onClick={()=>go('clientes')}><Users size={21}/><span>Clientes</span></button><button className="main-plus" aria-label="Nuevo préstamo" onClick={()=>setModal({type:'loan'})}><Plus size={25}/></button><button className={active==='cobros'?'selected':''} onClick={()=>go('cobros')}><CalendarCheck size={21}/><span>Cobros</span></button><button className={active==='mas'?'selected':''} onClick={()=>go('mas')}><MoreHorizontal size={21}/><span>Más</span></button></nav>;
  const emptyText = (title,subtitle)=> <Card><div className="empty-state"><CircleHelp size={27}/><strong>{title}</strong><p>{subtitle}</p></div></Card>;
  function renderHome(){
    const capitalAdded=rows(dbState.capitalMovements).filter(m=>m.businessId===currentId).reduce((a,m)=>a+Number(m.amount||0),0);
    const activeLoans=loans.filter(l=>loanBalance(dbState,l).principalDue>0);
    const next=activeLoans.slice().sort((a,b)=>(a.nextInterestDate||a.firstDueDate).localeCompare(b.nextInterestDate||b.firstDueDate)).slice(0,3);
    return <>
      <div className="topbar app-topbar"><button className="top-business" onClick={()=>go('negocios')} aria-label="Cambiar negocio"><Brand/><span className="current-business">{current?.name||'Mis negocios'}</span><ChevronDown size={15}/></button><button className="notification-icon" title="Abrir notificaciones" onClick={()=>setShowBell(v=>!v)}><Bell size={21}/>{unseenCount>0&&<span className="notice-count">{Math.min(99,unseenCount)}</span>}</button></div>
      {current ? <>
      <Card className="hero-dashboard"><div className="hero-top"><span>Capital disponible</span><button onClick={()=>go('capital')}>Editar</button></div><strong className="hero-amount">{money(totals.available)}</strong><div className="hero-split"><div><small>Capital total para prestar</small><strong>{money(totals.capitalTotal)}</strong></div><div><small>Capital adicional neto</small><strong>{money(capitalAdded)}</strong></div></div></Card>
      <div className="metric-grid compact-grid"><Mini icon={Landmark} label="Total prestado pendiente" value={money(totals.principalDue)}/><Mini icon={Wallet} label="Total por cobrar" value={money(totals.principalDue+totals.interestDue)} tone="purple"/><Mini icon={Users} label="Clientes" value={totals.clientCount}/><Mini icon={CreditCard} label="Préstamos activos" value={totals.loanCount} tone="green"/></div>
      <div className="section-title"><h3>Acciones rápidas</h3></div><div className="quick-grid"><button onClick={()=>setModal({type:'loan'})}><span className="quick-icon blue"><Plus size={22}/></span>Nuevo préstamo</button><button onClick={()=>setModal({type:'payment'})}><span className="quick-icon green"><CreditCard size={22}/></span>Registrar pago</button><button onClick={()=>go('clientes')}><span className="quick-icon violet"><Users size={22}/></span>Clientes</button><button onClick={()=>go('reportes')}><span className="quick-icon orange"><ChartColumnIncreasing size={22}/></span>Reportes</button></div>
      <div className="section-title"><h3>Próximos vencimientos</h3><button onClick={()=>go('vencimientos')}>Ver todos <ChevronRight size={15}/></button></div>
      <Card className="row-card">{next.map(l=><button className="list-row" key={l.id} onClick={()=>detailLoan(l)}><span className="tile-icon orange"><CalendarDays size={20}/></span><span className="grow"><strong>{dbState.clients[l.clientId]?.name||'Cliente'}</strong><small>{shortDate(l.nextInterestDate?addMonths(l.nextInterestDate,-1):l.firstDueDate)} · Préstamo #{l.id.slice(0,5).toUpperCase()}</small></span><span className="row-end"><b>{money(loanBalance(dbState,l).interestDue)}</b><ChevronRight size={15}/></span></button>)}{!next.length&&<p className="muted">Todavía no hay vencimientos. Crea un préstamo para empezar.</p>}</Card>
      <div className="home-footnote"><ShieldCheck size={15}/><span>Los negocios, clientes y sus movimientos permanecen separados.</span></div>
      </>:<Card><div className="empty-state"><Building2 size={30}/><h3>Empieza con tu primer negocio</h3><p>Indica el capital inicial para registrar préstamos y cobros.</p><Btn onClick={()=>setModal({type:'business'})} icon={Plus}>Crear negocio</Btn></div></Card>}
      {showBell&&<div className="bell-popover" role="dialog" aria-label="Avisos"><div className="flex between"><h3>Notificaciones</h3><IconButton icon={X} title="Cerrar" onClick={()=>setShowBell(false)}/></div><p className="muted">{unseenCount} avisos sin leer</p>{noticeItems.slice(0,4).map(n=><button className="list-row" key={n.id} onClick={()=>{setShowBell(false);setReadNotices(r=>({...r,[n.id]:true}));if(n.loanId)detailLoan(dbState.loans[n.loanId]);else go('respaldo')}}><span className={`tile-icon ${n.type==='vencimientos'?'red':n.type==='pagos'?'green':'blue'}`}>{n.type==='vencimientos'?<CalendarDays size={18}/>:<Receipt size={18}/>}</span><span className="grow"><strong>{n.title}</strong><small>{n.detail}</small></span>{!readNotices[n.id]&&<span className="notice-dot"/>}</button>)}{!noticeItems.length&&<p className="muted">No hay notificaciones.</p>}<Btn variant="soft" onClick={()=>{setShowBell(false);go('notificaciones')}}>Ver todas las notificaciones</Btn></div>}
    </>;
  }
  function renderNotifications(){
    const visible=noticeItems.filter(n=>noticeFilter==='todos'||n.type===noticeFilter);
    return <><Header title="Notificaciones" onBack={()=>go('inicio')} right={<button className="text-pill" onClick={()=>setReadNotices(r=>({...r,...Object.fromEntries(noticeItems.map(n=>[n.id,true]))}))}>Marcar leídas</button>}/>
      <Segmented value={noticeFilter} onChange={setNoticeFilter} options={[{label:'Todas',value:'todos'},{label:'Vencimientos',value:'vencimientos'},{label:'Pagos',value:'pagos'},{label:'Sistema',value:'sistema'}]}/>
      <Card>{visible.map(n=><button className={`list-row notice-item ${!readNotices[n.id]?'notice-unread':''}`} key={n.id} onClick={()=>{setReadNotices(r=>({...r,[n.id]:true}));if(n.loanId)detailLoan(dbState.loans[n.loanId]);else go('respaldo')}}><span className={`tile-icon ${n.type==='vencimientos'?'red':n.type==='pagos'?'green':'blue'}`}>{n.type==='vencimientos'?<CalendarDays size={20}/>:n.type==='pagos'?<Receipt size={20}/>:<ShieldCheck size={20}/>}</span><span className="grow"><strong>{n.title}</strong><small>{n.detail}</small><small>{shortDate(n.date)}</small></span>{!readNotices[n.id]&&<span className="notice-dot"/>}<ChevronRight size={16}/></button>)}{!visible.length&&<div className="empty-state"><Bell size={27}/><strong>Todo al día</strong><p>No hay avisos en esta categoría.</p></div>}</Card><p className="explainer">Los avisos se calculan a partir de tus préstamos y pagos guardados; esta versión los muestra dentro de PrestamoApp, no envía notificaciones push al teléfono cuando la página está cerrada.</p>
    </>;
  }
  function renderBusinesses(){return <><Header title="Mis negocios" onBack={()=>go('inicio')} right={<IconButton icon={Settings} title="Configuración" onClick={()=>go('configuracion')}/>}/><p className="muted">Selecciona el negocio con el que deseas trabajar.</p><div className="business-cards">{businesses.map(b=>{const x=businessBalance(dbState,b.id);return <div className={`business-choice ${currentId===b.id?'chosen':''}`} key={b.id}><button className="business-main" onClick={()=>{setBusinessId(b.id);go('inicio')}}><span className="business-symbol" style={{background:b.color}}><Building2 size={22}/></span><span className="grow"><strong>{b.name}</strong><small>{x.clientCount} clientes · {x.loanCount} préstamos activos</small><small className="text-green">{money(x.available)} disponible</small></span>{currentId===b.id?<CircleCheck color="#0871ff" size={21}/>:<ChevronRight size={18}/>}</button><button className="business-edit" title={`Editar ${b.name}`} onClick={()=>setModal({type:'business',business:b})}><Pencil size={16}/></button></div>})}</div><Btn onClick={()=>setModal({type:'business'})} variant="soft" icon={Plus}>Agregar nuevo negocio</Btn>{!businesses.length&&<p className="explainer">Crea tu primer negocio. Puedes agregar otros y cada uno tendrá sus propios saldos.</p>}</>}
  function renderCapital(){const entries=rows(dbState.capitalMovements).filter(e=>e.businessId===currentId).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return <><Header title="Capital del negocio" onBack={()=>go('inicio')} right={<IconButton icon={Pencil} title="Editar capital inicial" onClick={()=>setModal({type:'opening'})}/>}/><Card className="capital-overview"><div className="caption">Capital total para prestar</div><strong className="hero-money">{money(totals.capitalTotal)}</strong><div className="ratio-bar"><span style={{width:`${totals.capitalTotal?Math.max(0,totals.available/totals.capitalTotal*100):0}%`}}/></div><div className="metric-grid inside"><div className="soft-metric"><small>Disponible</small><strong className="text-green">{money(totals.available)}</strong></div><div className="soft-metric"><small>Prestado</small><strong>{money(totals.principalDue)}</strong></div></div></Card><Card><div className="list-row"><span className="grow">Capital inicial</span><strong>{money(current.openingCapital)}</strong><IconButton icon={Pencil} title="Corregir valor inicial" onClick={()=>setModal({type:'opening'})}/></div><div className="list-row"><span className="grow">Aportes y retiros posteriores</span><strong>{money(totals.capitalTotal-current.openingCapital)}</strong></div></Card><div className="two-actions"><Btn icon={Plus} onClick={()=>setModal({type:'capital',mode:'deposit'})}>Añadir capital</Btn><Btn icon={ArrowDownRight} variant="soft" onClick={()=>setModal({type:'capital',mode:'withdraw'})}>Retirar capital</Btn></div><div className="section-title"><h3>Historial de ajustes</h3></div><Card>{entries.length?entries.map(c=><div className="list-row" key={c.id}><span className={`tile-icon ${c.amount>0?'green':'red'}`}>{c.amount>0?<ArrowUpRight size={20}/>:<ArrowDownRight size={20}/>}</span><div className="grow"><strong>{c.category}</strong><small>{shortDate(c.date)} {c.note?`· ${c.note}`:''}</small></div><strong className={c.amount>0?'text-green':'text-red'}>{c.amount>0?'+':''}{money(c.amount)}</strong></div>):<p className="muted">Todavía no hay ajustes de capital.</p>}</Card><p className="explainer">Los intereses recibidos se muestran aparte: no aumentan automáticamente el capital para prestar. Si quieres reinvertirlos, registra un aporte.</p></>}
  function renderClients(){
    const dueClient=(c)=>loans.some(l=>l.clientId===c.id&&loanBalance(dbState,l).principalDue>0&&(l.nextInterestDate?addMonths(l.nextInterestDate,-1):l.firstDueDate)<today());
    const display=clients.filter(c=>c.name.toLowerCase().includes(search.toLowerCase())||(c.phone||'').includes(search)).filter(c=>{const active=loans.some(l=>l.clientId===c.id&&loanBalance(dbState,l).principalDue>0);return filter==='todos'||(filter==='activos'&&active)||(filter==='vencidos'&&dueClient(c))||(filter==='sin_saldo'&&!active)});
    const activeCount=clients.filter(c=>loans.some(l=>l.clientId===c.id&&loanBalance(dbState,l).principalDue>0)).length;
    return <><Header title="Clientes" right={<IconButton icon={Plus} title="Nuevo cliente" variant="blue" onClick={()=>setModal({type:'client'})}/>}/><div className="search-field"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar cliente..."/></div><Segmented options={[{value:'todos',label:`Todos ${clients.length}`},{value:'activos',label:`Activos ${activeCount}`},{value:'vencidos',label:'Vencidos'},{value:'sin_saldo',label:'Cancelados'}]} value={filter} onChange={setFilter}/><Card className="row-card">{display.map(c=>{const personal=loans.filter(l=>l.clientId===c.id&&loanBalance(dbState,l).principalDue>0),due=personal.reduce((a,l)=>a+loanBalance(dbState,l).principalDue,0);const late=dueClient(c);return <button className="list-row" key={c.id} onClick={()=>detailClient(c)}><span className="avatar">{pickName(c.name)}</span><span className="grow"><strong>{c.name}</strong><small>{c.phone||'Sin teléfono'} · {personal.length} préstamo(s)</small></span><span className="client-amount"><b>{money(due)}</b><small className={late?'text-red':due?'text-green':''}>{late?'Vencido':due?'Activo':'Cancelado'}</small></span><ChevronRight size={15}/></button>})}{!display.length&&<div className="empty-state"><Users size={26}/><strong>No hay clientes en este filtro</strong><p>Registra el primero con el botón +.</p></div>}</Card></>;
  }
  function renderClient(){if(!person)return <Header title="Cliente no encontrado" onBack={()=>go('clientes')}/>;const all=loans.filter(l=>l.clientId===clientId),pending=all.reduce((sum,l)=>sum+loanBalance(dbState,l).principalDue,0),interest=all.reduce((sum,l)=>sum+loanBalance(dbState,l).interestDue,0),lent=all.reduce((a,l)=>a+l.principal,0),collected=rows(dbState.payments).filter(p=>p.clientId===clientId&&!p.voidedAt).reduce((a,p)=>a+p.capital+p.interest,0);return <><Header title="Detalle del cliente" onBack={()=>go('clientes')} right={<IconButton icon={Pencil} title="Editar cliente" onClick={()=>setModal({type:'client',client:person})}/>}/><div className="person-heading"><span className="avatar large">{pickName(person.name)}</span><div><h2>{person.name}</h2><p>{person.phone||'Sin teléfono'}</p><span className="status green">{pending?'Préstamo activo':'Sin saldo de capital'}</span></div></div><div className="metric-grid"><Mini icon={Landmark} label="Total prestado" value={money(lent)}/><Mini icon={Wallet} label="Capital pendiente" value={money(pending)} tone="red"/><Mini icon={HandCoins} label="Intereses pendientes" value={money(interest)} tone="purple"/><Mini icon={Receipt} label="Total pagado" value={money(collected)} tone="green"/></div><div className="two-actions"><Btn icon={Plus} onClick={()=>setModal({type:'loan',clientId})}>Nuevo préstamo</Btn><Btn variant="soft" icon={CreditCard} onClick={()=>setModal({type:'payment',clientId})}>Registrar pago</Btn></div><div className="section-title"><h3>Préstamos del cliente</h3></div>{all.map(l=>{const bal=loanBalance(dbState,l);return <Card key={l.id}><button className="loan-item" onClick={()=>detailLoan(l)}><div className="flex between"><span className="status green">{bal.principalDue||bal.interestDue?'Activo':'Cancelado'}</span><small>#{l.id.slice(0,6).toUpperCase()} <ChevronRight size={14}/></small></div><strong className="big-money">{money(l.principal)}</strong><small>Interés: {l.rateBps/100}% mensual · {shortDate(l.startDate)}</small><div className="ratio-bar"><span style={{width:`${(bal.capitalPaid/l.principal)*100}%`}}/></div><div className="two-cols"><span>Capital pendiente <strong className="text-red">{money(bal.principalDue)}</strong></span><span>Interés pendiente <strong>{money(bal.interestDue)}</strong></span></div></button></Card>})}{!all.length&&emptyText('Sin préstamos','Puedes crear uno desde este perfil.')}<div className="section-title"><h3>Información</h3></div><Card><p className="muted">Teléfono: {person.phone||'No registrado'}</p><p className="muted">Notas: {person.note||'Sin observaciones'}</p></Card></>}
  function renderLoan(){if(!loan)return <Header title="Préstamo no encontrado" onBack={()=>go('clientes')}/>;const bal=loanBalance(dbState,loan),movement=rows(dbState.payments).filter(p=>p.loanId===loanId).sort((a,b)=>b.date.localeCompare(a.date));return <><Header title="Detalle del préstamo" onBack={()=>go('cliente')} right={<IconButton icon={Pencil} title="Editar condiciones futuras" onClick={()=>setModal({type:'loan',loan})}/>}/><span className="status green">{bal.principalDue||bal.interestDue?'Activo':'Cancelado'}</span><h1 className="very-big-money">{money(loan.principal)}</h1><p className="muted">{person?.name||'Cliente'} · #{loan.id.slice(0,8)}</p><Card><div className="summary-line"><span>Interés mensual</span><strong>{loan.rateBps/100}%</strong></div><div className="summary-line"><span>Desembolso</span><strong>{shortDate(loan.startDate)}</strong></div><div className="summary-line"><span>Primer vencimiento</span><strong>{shortDate(loan.firstDueDate)}</strong></div><div className="summary-line"><span>Modalidad</span><strong>{loan.mode==='monthly'?'Mensual':'Abonos manuales'}</strong></div><div className="summary-line"><span>Entregado por</span><strong>{PAYMENT_METHODS[loan.disbursementMethod||'cash']}{loan.disbursementReference?` · ${loan.disbursementReference}`:''}</strong></div><div className="summary-line"><span>Cálculo de interés</span><strong>{loan.interestPlan==='manual'?'Pactado manualmente':'Automático sobre saldo'}</strong></div><div className="ratio-bar"><span style={{width:`${bal.capitalPaid/loan.principal*100}%`}}/></div><div className="metric-grid inside"><div className="soft-metric"><small>Capital pagado</small><strong className="text-green">{money(bal.capitalPaid)}</strong></div><div className="soft-metric pink"><small>Capital pendiente</small><strong className="text-red">{money(bal.principalDue)}</strong></div><div className="soft-metric"><small>Intereses pagados</small><strong>{money(bal.interestPaid)}</strong></div><div className="soft-metric pink"><small>Intereses pendientes</small><strong>{money(bal.interestDue)}</strong></div></div></Card><div className="two-actions"><Btn icon={CreditCard} onClick={()=>setModal({type:'payment',clientId:loan.clientId,loanId:loan.id})}>Registrar pago</Btn><Btn variant="soft" icon={Pencil} onClick={()=>setModal({type:'interest',loanId:loan.id})}>Fijar interés</Btn></div><div className="section-title"><h3>Movimientos</h3></div><Card>{movement.map(p=><div key={p.id} className={`history-item ${p.voidedAt?'void':''}`}><span className="tile-icon green"><Receipt size={17}/></span><div className="grow"><strong>{shortDate(p.date)}</strong><small>{p.capital?`Capital ${money(p.capital)}`:''}{p.capital&&p.interest?' + ':''}{p.interest?`Interés ${money(p.interest)}`:''}{p.voidedAt?' · ANULADO':''} · {PAYMENT_METHODS[p.method||'cash']}</small></div>{!p.voidedAt&&<IconButton icon={Undo2} title="Anular pago con motivo" onClick={()=>setModal({type:'voidPayment',payment:p})}/>}</div>)}{!movement.length&&<p className="muted">Aún no se han registrado pagos.</p>}</Card><p className="explainer">En cálculo automático, los intereses futuros se recalculan con el capital pendiente. Puedes fijar un interés pactado manualmente con motivo; no se borran pagos anteriores.</p></>}
  function renderPayments(){const list=payments.filter(p=>paymentFilter==='todos'||(paymentFilter==='capital'?p.capital>0:p.interest>0));const sum=payments.filter(p=>p.date.slice(0,7)===month);return <><Header title="Cobros" right={<IconButton icon={Plus} title="Registrar pago" variant="blue" onClick={()=>setModal({type:'payment'})}/>}/><Labeled label="Mes del resumen"><input type="month" value={month} onChange={e=>setMonth(e.target.value)}/></Labeled><Card><span className="caption">Total recaudado en el mes</span><h2 className="big-money">{money(sum.reduce((a,p)=>a+p.capital+p.interest,0))}</h2><div className="two-cols"><span>Abonos a capital<strong className="text-green">{money(sum.reduce((a,p)=>a+p.capital,0))}</strong></span><span>Intereses cobrados<strong>{money(sum.reduce((a,p)=>a+p.interest,0))}</strong></span></div></Card><Segmented value={paymentFilter} onChange={setPaymentFilter} options={[{label:'Todos',value:'todos'},{label:'Capital',value:'capital'},{label:'Intereses',value:'interes'}]}/><div className="section-title"><h3>Movimientos registrados</h3></div><Card>{list.map(p=><div className="history-item" key={p.id}><span className="tile-icon green"><Receipt size={19}/></span><button className="grow history-body" onClick={()=>detailLoan(dbState.loans[p.loanId])}><strong>{dbState.clients[p.clientId]?.name||'Cliente'}</strong><small>{shortDate(p.date)} · {p.capital&&p.interest?'Capital e intereses':p.capital?'Abono a capital':'Intereses'} · {PAYMENT_METHODS[p.method||'cash']}</small></button><strong>{money(p.capital+p.interest)}</strong><IconButton icon={Ellipsis} title="Anular pago" onClick={()=>setModal({type:'voidPayment',payment:p})}/></div>)}{!list.length&&<p className="muted">No existen pagos registrados.</p>}</Card><Btn icon={Plus} onClick={()=>setModal({type:'payment'})}>Registrar un pago</Btn></>}
  function renderDue(){return <><Header title="Vencimientos" onBack={()=>go('inicio')}/><p className="muted">Información por préstamo y cliente; el registro del pago sigue siendo manual.</p><Card>{loans.filter(l=>loanBalance(dbState,l).principalDue>0||loanBalance(dbState,l).interestDue>0).sort((a,b)=>a.firstDueDate.localeCompare(b.firstDueDate)).map(l=><button className="list-row" key={l.id} onClick={()=>detailLoan(l)}><span className="tile-icon orange"><CalendarDays size={20}/></span><div className="grow"><strong>{dbState.clients[l.clientId]?.name}</strong><small>Primera fecha: {shortDate(l.firstDueDate)}</small></div><strong>{money(loanBalance(dbState,l).interestDue)}</strong><ChevronRight size={16}/></button>)}{!loans.length&&<p className="muted">No hay préstamos pendientes.</p>}</Card></>}
  function renderReport(){
    const m=monthlySummary(dbState,currentId,month);
    const lastMonths=Array.from({length:6},(_,i)=>{const dt=new Date(`${month}-15T12:00:00Z`);dt.setUTCMonth(dt.getUTCMonth()-(5-i));const key=dt.toISOString().slice(0,7);return {key,data:monthlySummary(dbState,currentId,key)}});
    const max=Math.max(1,...lastMonths.map(x=>x.data.capitalCollected+x.data.interestCollected));
    return <><Header title="Reportes mensuales" onBack={()=>go('mas')}/><Labeled label="Mes del reporte"><input type="month" value={month} onChange={e=>setMonth(e.target.value)}/></Labeled>
      <div className="metric-grid"><Mini icon={Landmark} label="Capital prestado (mes)" value={money(m.lent)}/><Mini icon={HandCoins} label="Capital recuperado (mes)" value={money(m.capitalCollected)} tone="green"/><Mini icon={Receipt} label="Intereses cobrados (mes)" value={money(m.interestCollected)} tone="orange"/><Mini icon={Wallet} label="Total cobrado (mes)" value={money(m.totalCollected)} tone="purple"/></div>
      <Card><h3>Estado del negocio</h3><div className="summary-line"><span>Capital invertido acumulado</span><strong>{money(totals.capitalTotal)}</strong></div><div className="summary-line"><span>Capital actualmente prestado</span><strong>{money(totals.principalDue)}</strong></div><div className="summary-line"><span>Capital recuperado histórico</span><strong>{money(totals.capitalRecovered)}</strong></div><div className="summary-line"><span>Capital disponible para prestar</span><strong className="text-green">{money(totals.available)}</strong></div><div className="summary-line"><span>Intereses cobrados históricos</span><strong>{money(totals.interestEarned)}</strong></div><div className="summary-line total"><span>Disponible + intereses cobrados*</span><strong>{money(totals.collectedCash)}</strong></div></Card>
      <Card><h3>Movimientos de {month}</h3><div className="summary-line"><span>Aportes de capital</span><strong>{money(m.capitalInjected)}</strong></div><div className="summary-line"><span>Retiros de capital</span><strong>{money(m.capitalWithdrawn)}</strong></div><div className="summary-line"><span>Entrada neta de dinero**</span><strong className={m.netCashFlow>=0?'text-green':'text-red'}>{money(m.netCashFlow)}</strong></div><div className="summary-line"><span>Ganancia bruta por intereses</span><strong>{money(m.interestProfit)}</strong></div></Card>
      <div className="section-title"><h3>Recaudo de los últimos seis meses</h3></div><Card><div className="bar-chart">{lastMonths.map(({key,data})=><div className="bar-col" key={key}><div title={money(data.totalCollected)} className="bar" style={{height:`${Math.max(2,data.totalCollected/max*140)}px`}}/><small>{key.slice(5)}</small></div>)}</div></Card>
      <Card><h3>Dinero por canal · {month}</h3>{Object.entries(PAYMENT_METHODS).map(([key,label])=><div className="method-summary" key={key}><strong>{label}</strong><span>Entregado {money(m.byMethod[key].lent)}</span><span>Recibido {money(m.byMethod[key].received)}</span></div>)}</Card>
      <p className="explainer">* Es una disponibilidad teórica si todos los intereses cobrados siguen en el negocio: no incluye gastos, transferencias internas ni intereses retirados. ** Incluye préstamos, recaudos y movimientos de capital, pero no otros gastos. La ganancia indicada es bruta, antes de gastos e impuestos. Cada negocio tiene sus propios reportes.</p>
    </>;
  }
  function renderMore(){const item=(Icon,title,to,accent)=> <button className="settings-row" onClick={()=>go(to)}><span className={`tile-icon ${accent||'blue'}`}><Icon size={20}/></span><strong>{title}</strong><ChevronRight size={17}/></button>;return <><Header title="Más"/><Card className="settings">{item(ChartColumnIncreasing,'Reportes','reportes','purple')}{item(History,'Movimientos del negocio','auditoria')}{item(Building2,'Gestión de negocios','negocios')}{item(Bell,'Recordatorios','notificaciones','orange')}{item(ShieldCheck,'Respaldo de datos','respaldo','green')}{item(Settings,'Configuración','configuracion')}{item(CircleHelp,'Ayuda','ayuda')}</Card>{enabled?<Btn variant="outline-red" icon={LogOut} onClick={async()=>{await signOut(auth);inform('Sesión cerrada.')}}>Cerrar sesión</Btn>:<p className="explainer">Modo demostración local: no guarda información en la nube. Conecta Firebase antes de usar datos reales.</p>}</>}
  function renderSettings(){return <><Header title="Configuración" onBack={()=>go('mas')}/><h3 className="group-label">Mi cuenta</h3><Card className="settings"><button className="settings-row" onClick={()=>go('cuenta')}><UserRound size={19}/><strong>Editar perfil / consultar cuenta</strong><ChevronRight size={16}/></button><button className="settings-row" onClick={()=>{if(enabled){setLoginMode('reset');inform('Para cambiar la contraseña, cierra sesión y usa Recuperar contraseña.')}else inform('La demo no dispone de contraseña.')}}><LockKeyhole size={19}/><strong>Cambiar contraseña</strong><ChevronRight size={16}/></button></Card><h3 className="group-label">Preferencias</h3><Card className="settings"><div className="settings-row"><Wallet size={19}/><strong>Moneda</strong><span className="settings-value">COP · $</span></div><div className="settings-row"><CalendarDays size={19}/><strong>Inicio de semana</strong><span className="settings-value">Lunes</span></div><div className="settings-row"><Bell size={19}/><strong>Notificaciones en la app</strong><input type="checkbox" className="ios-toggle" checked={notificationsEnabled} onChange={e=>setNotificationsEnabled(e.target.checked)}/></div></Card><h3 className="group-label">Respaldo de datos</h3><Card className="settings"><button className="settings-row" onClick={()=>go('respaldo')}><ShieldCheck size={19}/><strong>Firebase y Google Sheets</strong><ChevronRight size={16}/></button><button className="settings-row" onClick={()=>go('auditoria')}><History size={19}/><strong>Historial de movimientos</strong><ChevronRight size={16}/></button></Card></>}
  function renderHelp(){return <><Header title="Ayuda" onBack={()=>go('mas')}/><Card><h3>¿Cómo administrar PrestamoApp?</h3><p className="muted">Crea un negocio, registra el capital y luego añade clientes y préstamos. Para registrar un pago, elige al cliente y el préstamo específico; separa capital e intereses.</p><p className="muted">En el detalle del préstamo puedes fijar un interés manual para cada período. Cada corrección de capital, pago o interés queda registrada en el historial.</p></Card><Btn onClick={()=>go('respaldo')} icon={ShieldCheck} variant="soft">Consultar respaldos</Btn></>}
  function renderAudit(){return <><Header title="Historial de operaciones" onBack={()=>go('mas')}/><Card>{rows(dbState.audit).filter(a=>!a.businessId||a.businessId===currentId).sort((a,b)=>b.at.localeCompare(a.at)).slice(0,250).map(a=><div key={a.id} className="history-item"><span className="tile-icon blue"><History size={18}/></span><div className="grow"><strong>{({CREATE_LOAN:'Préstamo creado',CREATE_PAYMENT:'Pago registrado',VOID_PAYMENT:'Pago anulado',CAPITAL_MOVE:'Movimiento de capital',EDIT_OPENING:'Capital inicial corregido',CREATE_CLIENT:'Cliente creado',EDIT_CLIENT:'Cliente editado',BILL_INTEREST:'Intereses mensuales',CREATE_BUSINESS:'Negocio creado',EDIT_BUSINESS:'Negocio editado',EDIT_LOAN:'Préstamo editado',SET_PERIOD_INTEREST:'Interés pactado manualmente'})[a.kind]||a.kind}</strong><small>{new Date(a.at).toLocaleString('es-CO')} {a.detail?`· ${a.detail}`:''}</small></div></div>)}{!rows(dbState.audit).length&&<p className="muted">Aún no hay operaciones.</p>}</Card></>}
  function renderBackup(){const online=enabled&&!!user;return <><Header title="Respaldo de información" onBack={()=>go('mas')} right={online?<IconButton icon={RefreshCw} title="Actualizar estado" onClick={loadBackup}/>:null}/>{!enabled&&<div className="warning"><CircleAlert size={19}/> Modo demostración: tus datos están únicamente en este navegador. No hay copias automáticas ni Google Sheets conectado.</div>}
    <Card><div className="flex between"><span className="tile-icon green"><FileSpreadsheet size={23}/></span><span className={`status ${freeBackup?.status==='ok'?'green':'red'}`}>{freeBackup?.status==='ok'?'Copia informada':'Falta verificar'}</span></div><h3>Respaldo gratis · Google Apps Script</h3><p className="muted">Copia tu Firebase a Google Sheets y conserva JSON independientes en Google Drive cada cuatro horas, con la app cerrada. Requiere instalar un script privado en tu cuenta Google.</p>{freeBackup?.at&&<small>Último intento: {new Date(freeBackup.at).toLocaleString('es-CO')} · Revisión {freeBackup.revision||'—'}</small>}{freeBackup?.message&&<div className="warning"><CircleAlert size={16}/>{freeBackup.message}</div>}{freeBackup?.sheetUrl&&<a className="link-card" href={freeBackup.sheetUrl} target="_blank" rel="noopener noreferrer">Abrir hoja de respaldo <ArrowUpRight size={15}/></a>}<p className="explainer">Solo aparece verificado después de una ejecución real de Apps Script. Consulta la guía CONFIGURAR_RESPALDO_GRATIS.md del proyecto.</p></Card>
    <Card><div className="flex between"><span className="tile-icon green"><Cloud size={23}/></span><span className={`status ${online?'green':'red'}`}>{online?'Configurado con Firebase':'No configurado'}</span></div><h3>Base de datos principal</h3><p className="muted">{online?'Los cambios confirmados se guardan en Firebase Realtime Database.':'Configura Firebase para guardar y sincronizar entre dispositivos.'}</p></Card>
    {paidBackupEnabled&&<>
    <Card><div className="flex between"><span className="tile-icon purple"><ShieldCheck size={23}/></span><span className={`status ${backupStatus?.lastCloudBackup?'green':'red'}`}>{backupStatus?.lastCloudBackup?'Última copia registrada':'Por verificar'}</span></div><h3>Copia automática diaria</h3><p className="muted">Copias JSON comprimidas en Cloud Storage, todos los días a las 02:00 (hora de Colombia), una vez desplegadas las funciones programadas.</p>{backupStatus?.lastCloudBackup&&<small>Última copia: {new Date(backupStatus.lastCloudBackup).toLocaleString('es-CO')}</small>}<Btn variant="soft" icon={Cloud} disabled={!online||backupBusy} onClick={manualCloudBackup}>Crear copia en la nube ahora</Btn>{backupStatus?.lastCloudBackup&&<button className="restore-link" onClick={()=>restoreRemote('cloud')} disabled={backupBusy}>Recuperar última copia de Storage</button>}</Card>
    <Card><div className="flex between"><span className="tile-icon green"><FileSpreadsheet size={23}/></span><span className={`status ${backupStatus?.googleConnected?'green':'red'}`}>{backupStatus?.googleConnected?'Conectado':'Sin conectar'}</span></div><h3>Google Sheets</h3><p className="muted">Una hoja por cuenta, actualizada durante cada copia diaria y también al ejecutar una copia manual. Contiene tablas y un respaldo JSON para recuperar los datos.</p>{backupStatus?.lastSheetsSync&&<small>Última sincronización: {new Date(backupStatus.lastSheetsSync).toLocaleString('es-CO')}</small>}{backupStatus?.sheetUrl&&<a className="link-card" href={backupStatus.sheetUrl} target="_blank" rel="noopener noreferrer">Abrir archivo en Google Sheets <ArrowUpRight size={15}/></a>}{backupStatus?.googleConnected?<><button className="restore-link" disabled={backupBusy} onClick={()=>restoreRemote('sheets')}>Recuperar datos desde Google Sheets</button><Btn variant="light" onClick={disconnectSheets} disabled={backupBusy}>Desconectar Google Sheets</Btn></>:<Btn variant="soft" icon={FileSpreadsheet} onClick={connectSheets} disabled={!online||backupBusy}>Conectar Google Sheets</Btn>}</Card>
    </>}
    <Card><div className="flex between"><span className="tile-icon blue"><FileDown size={23}/></span></div><h3>Respaldo manual descargable</h3><p className="muted">Descarga un archivo JSON con toda tu información, independiente de Google o Firebase.</p><div className="two-actions"><Btn icon={Download} onClick={saveFile}>Descargar JSON</Btn><Btn variant="soft" icon={Upload} onClick={()=>fileInput.current?.click()}>Restaurar</Btn></div><input type="file" accept=".json,application/json" ref={fileInput} onChange={restoreFile} hidden/></Card>
    {paidBackupEnabled&&backupStatus?.lastError&&<div className="warning"><CircleAlert size={18}/><span>Última incidencia del respaldo: {backupStatus.lastError}</span></div>}<p className="explainer">Ningún sistema puede prometer riesgo cero. Revisa la fecha de la última copia y prueba periódicamente la restauración. El respaldo gratuito solo se considera activo cuando muestra una copia real con fecha. Las funciones alternativas de pago requieren su propia configuración.</p></>}
  function renderAccount(){return <><Header title="Mi cuenta" onBack={()=>go('mas')}/><Card><strong>{user?.email||'Demostración local'}</strong>{user?.uid&&<p className="muted">ID de cuenta para configurar el respaldo: <code style={{userSelect:'all',overflowWrap:'anywhere'}}>{user.uid}</code></p>}<p className="muted">Cuenta con {businesses.length} negocios registrados.</p></Card><Btn onClick={()=>go('respaldo')} icon={ShieldCheck}>Revisar respaldos</Btn></>}
  function renderPage(){switch(page){case 'inicio':return renderHome();case 'negocios':return renderBusinesses();case 'capital':return renderCapital();case 'clientes':return renderClients();case 'cliente':return renderClient();case 'prestamo':return renderLoan();case 'cobros':return renderPayments();case 'vencimientos':return renderDue();case 'notificaciones':return renderNotifications();case 'reportes':return renderReport();case 'mas':return renderMore();case 'configuracion':return renderSettings();case 'ayuda':return renderHelp();case 'auditoria':return renderAudit();case 'respaldo':return renderBackup();case 'cuenta':return renderAccount();default:return renderHome()}}
  const noNav=['capital','negocios','prestamo','cliente','reportes','vencimientos','notificaciones','respaldo','auditoria','cuenta','configuracion','ayuda'];
  if(!ready)return <div className="splash"><Brand large/><p>Preparando PrestamoApp...</p></div>;
  if(showWelcome)return <div className="splash"><Brand large/><p>Tus préstamos, siempre organizados</p><div className="loading-dots"><i/><i/><i/></div></div>;
  if(enabled&&!user)return <div className="auth"><Brand large/><h2>{loginMode==='register'?'Crear cuenta':loginMode==='reset'?'Recuperar contraseña':'Bienvenido'}</h2><p>Organiza tus negocios y préstamos desde tu celular.</p><form onSubmit={login}><Labeled label="Correo electrónico"><input required type="email" autoComplete="email" placeholder="correo@ejemplo.com" value={loginForm.email} onChange={txt(setLoginForm,'email')}/></Labeled>{loginMode!=='reset'&&<Labeled label="Contraseña"><div className="password-box"><input required minLength={6} autoComplete={loginMode==='register'?'new-password':'current-password'} type={showPassword?'text':'password'} value={loginForm.password} placeholder="Contraseña" onChange={txt(setLoginForm,'password')}/><button type="button" onClick={()=>setShowPassword(!showPassword)}>{showPassword?<EyeOff size={18}/>:<Eye size={18}/>}</button></div></Labeled>}<Btn type="submit" disabled={busy}>{busy?'Comprobando...':loginMode==='register'?'Crear cuenta':loginMode==='reset'?'Enviar enlace':'Ingresar'}</Btn></form><button className="text-link" onClick={()=>setLoginMode(loginMode==='reset'?'login':'reset')}>{loginMode==='reset'?'Volver a iniciar sesión':'¿Olvidaste tu contraseña?'}</button><button className="btn btn-light" onClick={()=>setLoginMode(loginMode==='register'?'login':'register')}>{loginMode==='register'?'Ya tengo cuenta':'Crear cuenta'}</button></div>;
  return <div className="app-frame"><div className="app-content">{!enabled&&<div className="demo-banner"><CloudOff size={14}/> DEMOSTRACIÓN LOCAL · sin copia automática <button onClick={()=>go('respaldo')}>Ver</button></div>}{current||['inicio','negocios','mas','respaldo','cuenta'].includes(page)?renderPage():<><Header title="Configura tu negocio" onBack={()=>go('inicio')}/><Btn onClick={()=>setModal({type:'business'})}>Crear negocio</Btn></>}</div>{!noNav.includes(page)&&nav(page==='cobros'?'cobros':page==='clientes'||page==='cliente'||page==='prestamo'?'clientes':page==='mas'?'mas':'inicio')}{modal&&<Editor type={modal.type} initial={modal} close={()=>setModal(null)} save={async(kind,payload)=>{const okay=await doAction(kind,payload);if(okay)setModal(null);return okay}} s={dbState} businessId={currentId} clients={clients} loans={loans} totals={totals} busy={busy} selectBusiness={b=>{setBusinessId(b);setModal(null);go('inicio')}} switchToCreate={()=>setModal({type:'business'})}/>}{toast&&<div className="toast" role="status">{toast}<button onClick={()=>setToast('')}><X size={16}/></button></div>}</div>;
}
function Editor({type,initial,close,save,s,businessId,clients,loans,totals,busy,selectBusiness,switchToCreate}){
  const existing=initial.client||initial.loan||null;
  const [f,setF]=useState(()=>{
    if(type==='business')return {name:initial.business?.name||'',openingCapital:String(initial.business?.openingCapital||0),color:initial.business?.color||COLORS[0]};
    if(type==='capital')return {amount:'',note:'',date:today(),method:'cash',type:initial.mode||'deposit'};
    if(type==='opening')return {amount:String(s.businesses[businessId]?.openingCapital||0)};
    if(type==='client')return {name:initial.client?.name||'',phone:initial.client?.phone||'',note:initial.client?.note||''};
    if(type==='loan')return {clientId:initial.clientId||initial.loan?.clientId||clients[0]?.id||'',principal:String(initial.loan?.principal||''),ratePct:String((initial.loan?.rateBps??2000)/100),startDate:today(),firstDueDate:addMonths(today()),mode:initial.loan?.mode||'manual',interestPlan:initial.loan?.interestPlan||'automatic',manualFirstInterest:String(initial.loan?.charges?.first?.origin==='manual'?initial.loan?.charges?.first?.amount:0),disbursementMethod:initial.loan?.disbursementMethod||'cash',disbursementReference:initial.loan?.disbursementReference||'',notes:initial.loan?.notes||''};
    if(type==='payment')return {loanId:initial.loanId||loans.find(l=>l.clientId===initial.clientId)?.id||loans[0]?.id||'',capital:'',interest:'',method:'cash',date:today(),note:''};
    if(type==='interest')return {loanId:initial.loanId,periodDate:s.loans[initial.loanId]?.firstDueDate||today(),amount:'',reason:''};
    return {reason:''};
  });
  const [paymentClient,setPaymentClient]=useState((initial.clientId&&loans.some(l=>l.clientId===initial.clientId)?initial.clientId:null)||s.loans[f.loanId]?.clientId||clients.find(c=>loans.some(l=>l.clientId===c.id))?.id||'');
  const currentLoan=s.loans[f.loanId];const bal=currentLoan?loanBalance(s,currentLoan):null;
  const preview={capital:int(f.capital),interest:int(f.interest)};
  const input=(label,key,type='text',options={})=><Labeled label={label}><input type={type} value={f[key]} onChange={txt(setF,key)} required={!options.optional} min={options.min} max={options.max} step={options.step} placeholder={options.placeholder}/></Labeled>;
  const choice=(label,key,opts)=><Labeled label={label}><select value={f[key]} onChange={txt(setF,key)}>{opts.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select></Labeled>;
  async function submit(e){e.preventDefault();let kind,p;
    if(type==='business'){kind=initial.business?'EDIT_BUSINESS':'CREATE_BUSINESS';p={id:initial.business?.id||id(),businessId,name:f.name,color:f.color,openingCapital:Number(f.openingCapital)}}
    if(type==='capital'){kind='CAPITAL_MOVE';p={id:id(),businessId,amount:Number(f.amount),type:f.type,method:f.method,date:f.date,note:f.note}}
    if(type==='opening'){kind='EDIT_OPENING';p={businessId,amount:Number(f.amount)}}
    if(type==='client'){kind=initial.client?'EDIT_CLIENT':'CREATE_CLIENT';p={id:initial.client?.id||id(),businessId,name:f.name,phone:f.phone,note:f.note}}
    if(type==='loan'){kind=initial.loan?'EDIT_LOAN':'CREATE_LOAN';p={id:initial.loan?.id||id(),businessId,clientId:f.clientId,principal:Number(f.principal),rateBps:Math.round(Number(f.ratePct)*100),startDate:f.startDate,firstDueDate:f.firstDueDate,mode:f.mode,interestPlan:f.interestPlan,manualFirstInterest:Number(f.manualFirstInterest||0),disbursementMethod:f.disbursementMethod,disbursementReference:f.disbursementReference,notes:f.notes}}
    if(type==='payment'){kind='CREATE_PAYMENT';p={id:id(),businessId,loanId:f.loanId,capital:Number(f.capital||0),interest:Number(f.interest||0),method:f.method,date:f.date,note:f.note}}
    if(type==='voidPayment'){kind='VOID_PAYMENT';p={id:initial.payment.id,reason:f.reason}}
    if(type==='interest'){kind='SET_PERIOD_INTEREST';p={businessId,loanId:f.loanId,periodDate:f.periodDate,amount:Number(f.amount),reason:f.reason}}
    await save(kind,p);
  }
  const title={switch:'Mis negocios',business:initial.business?'Editar negocio':'Nuevo negocio',capital:f.type==='withdraw'?'Retirar capital':'Agregar capital',opening:'Corregir capital inicial',client:initial.client?'Editar cliente':'Nuevo cliente',loan:initial.loan?'Editar préstamo':'Nuevo préstamo',payment:'Registrar pago',interest:'Fijar interés manual',voidPayment:'Anular pago'}[type];
  return <div className="modal-backdrop" onClick={close}><div className="modal-sheet" onClick={e=>e.stopPropagation()}><div className="modal-head"><h2>{title}</h2><IconButton icon={X} title="Cerrar" onClick={close}/></div>{type==='switch'?<><div className="modal-inner">{rows(s.businesses).map(b=><button className="list-row" key={b.id} onClick={()=>selectBusiness(b.id)}><span className="tile-icon blue"><Building2 size={21}/></span><span className="grow"><strong>{b.name}</strong><small>{businessBalance(s,b.id).clientCount} clientes · {businessBalance(s,b.id).loanCount} préstamos</small></span>{businessId===b.id?<CircleCheck color="#155cfb" size={19}/>:<ChevronRight size={18}/>}</button>)}<Btn icon={Plus} variant="soft" onClick={switchToCreate}>Agregar nuevo negocio</Btn></div></>:<form className="modal-inner" onSubmit={submit}>
    {type==='business'&&<>{input('Nombre del negocio','name')}{!initial.business&&input('Capital inicial (COP)','openingCapital','number',{min:0})}<span className="field-label">Color del negocio</span><div className="color-dots">{COLORS.map(c=><button type="button" key={c} className={f.color===c?'chosen':''} style={{background:c}} onClick={()=>setF(v=>({...v,color:c}))}>{f.color===c?<Check size={17}/>:null}</button>)}</div></>}
    {type==='capital'&&<>{choice('Tipo de movimiento','type',[{value:'deposit',label:'Agregar capital'},{value:'withdraw',label:'Retirar capital'}])}{input('Monto del movimiento (COP)','amount','number',{min:1})}{choice('Medio del movimiento','method',METHODS)}{input('Fecha','date','date')}{input('Motivo u observaciones','note','text',{optional:true})}<div className="subtle-info">Disponible ahora: {money(totals.available)}. Después: {money(totals.available+(f.type==='withdraw'?-1:1)*Number(f.amount||0))}</div></>}
    {type==='opening'&&<>{input('Capital inicial corregido (COP)','amount','number',{min:0})}<p className="explainer">Se guarda en la bitácora el valor anterior y el nuevo. No puedes bajar el capital por debajo de lo ya prestado.</p></>}
    {type==='client'&&<>{input('Nombre completo','name')}{input('Teléfono','phone','tel',{optional:true})}<Labeled label="Observaciones"><textarea value={f.note} onChange={txt(setF,'note')} rows={3} placeholder="Notas opcionales..."/></Labeled></>}
    {type==='loan'&&<>{!initial.loan&&choice('Cliente','clientId',clients.length?clients.map(c=>({label:c.name,value:c.id})):[{label:'Primero registra un cliente',value:''}])}{!initial.loan&&input('Monto del préstamo (COP)','principal','number',{min:1})}{input('Interés mensual (%)','ratePct','number',{min:0,max:100,step:0.01})}{!initial.loan&&<>{input('Fecha del préstamo','startDate','date')}{input('Primer vencimiento','firstDueDate','date')}</>}{!initial.loan&&<>{choice('Medio de entrega del dinero','disbursementMethod',METHODS)}{input('Referencia de entrega (opcional)','disbursementReference','text',{optional:true})}</>}{choice('Forma de pago','mode',[{value:'manual',label:'Abonos manuales, sin límite de pagos'},{value:'monthly',label:'Mensual'}])}{choice('Cómo calcular los intereses','interestPlan',[{value:'automatic',label:'Automático sobre capital pendiente'},{value:'manual',label:'Yo fijo manualmente el interés cada período'}])}{!initial.loan&&f.interestPlan==='manual'&&input('Interés inicial acordado (COP)','manualFirstInterest','number',{min:0})}<Labeled label="Observaciones"><textarea value={f.notes} onChange={txt(setF,'notes')} rows={2}/></Labeled>{!initial.loan&&<div className="subtle-info">Disponible antes: {money(totals.available)}. Disponible después: {money(totals.available-Number(f.principal||0))}. Primer interés: {money(Math.round(Number(f.principal||0)*Number(f.ratePct||0)/100))}.</div>}{initial.loan&&<p className="explainer">Cambiar la tasa solo modifica los intereses que se causen en períodos futuros. No se modifica el saldo histórico.</p>}</>}
    {type==='payment'&&<>
      <Labeled label="Cliente"><select value={paymentClient} onChange={e=>{const client=e.target.value;setPaymentClient(client);setF(v=>({...v,loanId:loans.find(l=>l.clientId===client)?.id||''}))}}>{clients.filter(c=>loans.some(l=>l.clientId===c.id)).map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></Labeled>
      <Labeled label="Préstamo al que corresponde el pago"><select value={f.loanId} onChange={txt(setF,'loanId')}>{loans.filter(l=>l.clientId===paymentClient).map(l=>{const b=loanBalance(s,l);return <option key={l.id} value={l.id}>#{l.id.slice(0,6).toUpperCase()} · Capital {money(b.principalDue)} · Interés {money(b.interestDue)}</option>})}</select></Labeled>
      {input('Fecha del pago','date','date')}
      {choice('Recibido por','method',METHODS)}
      {input('Abono a capital (COP)','capital','number',{min:0,optional:true})}
      {input('Pago de intereses (COP)','interest','number',{min:0,optional:true})}
      <Labeled label="Observaciones"><textarea value={f.note} onChange={txt(setF,'note')} rows={2} placeholder="Notas del pago (opcional)"/></Labeled>
      {bal&&<div className="subtle-info">Puedes registrar cualquier cantidad de abonos, separando capital e intereses. Si pactaste otro interés, usa «Fijar interés» en la ficha del préstamo para que el saldo y la condición queden registrados.</div>}{bal&&<div className="preview-balance"><h3>Resultado del pago</h3><div className="summary-line"><span>Capital pendiente actual</span><strong>{money(bal.principalDue)}</strong></div><div className="summary-line"><span>Capital después del pago</span><strong className="text-green">{money(bal.principalDue-preview.capital)}</strong></div><div className="summary-line"><span>Interés causado pendiente</span><strong>{money(bal.interestDue)}</strong></div><div className="summary-line"><span>Intereses después del pago</span><strong>{money(bal.interestDue-preview.interest)}</strong></div><div className="summary-line"><span>Próximo interés mensual estimado</span><strong>{money(Math.round(Math.max(0,bal.principalDue-preview.capital)*currentLoan.rateBps/10000))}</strong></div><div className="summary-line total"><span>Total recibido</span><strong>{money(preview.capital+preview.interest)}</strong></div></div>}
    </>}
    {type==='interest'&&<><div className="subtle-info">El importe que escribas sustituye al interés causado del período elegido. Puedes establecerlo en cero, pero no por debajo de intereses ya pagados. Queda en la bitácora.</div>{input('Fecha de vencimiento del período','periodDate','date')}{input('Interés acordado del período (COP)','amount','number',{min:0})}{input('Motivo o acuerdo con el cliente','reason')}</>}
    {type==='voidPayment'&&<><div className="warning"><CircleAlert size={19}/> La anulación restaurará los saldos de capital e intereses. La operación quedará en el historial.</div>{input('Motivo de la anulación','reason')}</>}
    {type!=='switch'&&<Btn type="submit" disabled={busy||(type==='loan'&&!initial.loan&&!clients.length)||(type==='payment'&&!loans.length)}>{busy?'Guardando...':type==='voidPayment'?'Confirmar anulación':'Guardar'}</Btn>}
  </form>}</div></div>;
}
// Hook de integración para el selector de negocios.
createRoot(document.getElementById('root')).render(<App/>);
